  const stack = []
  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    for (const d of graph.get(n).deps) {
      if (state.get(d) === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!state.has(d)) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(n, 2)
    return null
